    "content": "name: Production Build & Deployment Pipeline\n\non:\n  push:\n    branches:\n      - main\n  pull_request:\n    branches:\n      - main\n  workflow_dispatch:\n\njobs:\n  validate-and-build:\n    name: Lint, Typecheck, Build & Verification\n    runs-on: ubuntu-latest\n\n    steps:\n      - name: Checkout Source Code\n        uses: actions/checkout@v4\n\n      - name: Setup Node.js 20\n        uses: actions/setup-node@v4\n        with:\n          node-version: '20'\n          cache: 'npm'\n\n      - name: Setup Python Environment\n        uses: actions/setup-python@v5\n        with:\n          python-version: '3.11'\n\n      - name: Install Dependencies\n        run: |\n          npm ci || npm install\n\n      - name: TypeScript Static Typecheck\n        run: |\n          npx tsc --noEmit\n\n      - name: Build Next.js Application\n        run: |\n          npm run build\n        env:\n          NODE_ENV: production\n          NEXT_PUBLIC_APP_URL: https://shipguard-saas.vercel.app\n          PRODUCTION_CLIENT_URL: https://shipguard-saas.vercel.app\n\n      - name: Start Production Server in Background\n        run: |\n          npm start &\n          echo \"Waiting for server to become healthy on port 3000...\"\n          for i in $(seq 1 30); do\n            if curl -s http://127.0.0.1:3000/api/v1/gate-check > /dev/null 2>&1; then\n              echo \"Server is listening and responsive!\"\n              break\n            fi\n            sleep 1\n          done\n\n      - name: Run Functional Principles Verification Suite\n        run: |\n          python scratch/test_functional_principles.py\n        env:\n          TEST_BASE_URL: http://127.0.0.1:3000\n"
