    "path": ".github/workflows/shipguard-gate.yml",
    "content": "name: ShipGuard AI Release Gate Audit\n\non:\n  push:\n    branches: [ main, master, develop ]\n  pull_request:\n    branches: [ main, master, develop ]\n\njobs:\n  shipguard-release-gate:\n    name: ShipGuard Production Pre-flight Audit\n    runs-on: ubuntu-latest\n\n    steps:\n      - name: Checkout Code Repository\n        uses: actions/checkout@v4\n\n      - name: Setup Node.js Environment\n        uses: actions/setup-node@v4\n        with:\n          node-version: '20'\n          cache: 'npm'\n\n      - name: Run TypeScript & Security Lint Check\n        run: |\n          npm ci || npm install\n          npx tsc --noEmit\n\n      - name: Trigger ShipGuard Release Gate API Audit\n        env:\n          SHIPGUARD_API_URL: ${{ secrets.SHIPGUARD_API_URL || 'https://shipguard-saas.vercel.app/api/v1/gate-check' }}\n          SLACK_WEBHOOK_URL: ${{ secrets.SLACK_WEBHOOK_URL }}\n          DISCORD_WEBHOOK_URL: ${{ secrets.DISCORD_WEBHOOK_URL }}\n        run: |\n          echo \"\ud83d\ude80 Triggering ShipGuard Release Gate Audit for repository: ${{ github.repository }}...\"\n          RESPONSE=$(curl -s -X POST \"$SHIPGUARD_API_URL\" \\\n            -H \"Content-Type: application/json\" \\\n            -H \"Authorization: Bearer ${{ secrets.GITHUB_TOKEN }}\" \\\n            -d \"{\\\"repoUrl\\\": \\\"${{ github.repository }}\\\", \\\"slackWebhookUrl\\\": \\\"$SLACK_WEBHOOK_URL\\\", \\\"discordWebhookUrl\\\": \\\"$DISCORD_WEBHOOK_URL\\\"}\")\n          \n          echo \"Audit Response: $RESPONSE\"\n          GATE_STATUS=$(echo \"$RESPONSE\" | jq -r '.gateStatus // \"FAILED\"')\n          READINESS_SCORE=$(echo \"$RESPONSE\" | jq -r '.readinessScore // 0')\n          \n          echo \"--------------------------------------------------\"\n          echo \"\ud83d\udcca ShipGuard Gate Status: $GATE_STATUS\"\n          echo \"\ud83d\udcca Production Readiness Score: $READINESS_SCORE%\"\n          echo \"--------------------------------------------------\"\n          \n          if [ \"$GATE_STATUS\" = \"FAILED\" ]; then\n            echo \"\u274c Release BLOCKED! Critical security vulnerabilities detected.\"\n            exit 1\n          else\n            echo \"\u2705 Release Gate PASSED! Application is ready for production deployment.\"\n          fi\n"
